'use strict';
// Inventory workflows restored on the same server ledger as manufacturing.
let inventoryTools={classifications:[],settings:{}}, classEdit=null, inventoryFilter={q:'',warehouse:'',category:'',brand:'',type:'',view:'summary'}, operationFilter={}, reportKind='valuation', reportDays=30, reportWarehouse='', reportProduct='', reportCache=null, forecastCache=null, auditCache=null, archiveCache=null;
const fmt=n=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:6}).format(Number(n||0));
const rupiah=n=>'Rp '+fmt(n);
const originalRefresh=refresh;
refresh=async function(){await originalRefresh();if(catalog.active)inventoryTools=await api('/api/manufacturing/inventory-tools');reportCache=forecastCache=auditCache=null;};
const originalRender=render;
render=function(){
 const extra={dashboard:renderDashboard,classification:renderClassification,reports:renderReports,forecast:renderForecast,audit:renderAudit,settings:renderSettings,archive:renderArchive};
 if(extra[tab]){const chosen=tab;tab='setup';originalRender();tab=chosen;$('#content').innerHTML=extra[tab]();}else originalRender();
 const groups=[['Ringkasan',[['dashboard','Dashboard'],['stock','Stok & pemakaian'],['movements','Kartu mutasi']]],['Transaksi',[['purchasing','Pembelian / PO'],['transfers','Transfer'],['opname','Stock opname'],['scrap','Scrap'],['forecast','Forecast pembelian']]],['Manufaktur',[['kitchens','Dapur & gudang'],['boms','BOM / resep']]],['Master & laporan',[['products','Produk'],['classification','Kategori, merek & jenis'],['reports','Laporan'],...(isAdmin()?[['access','Pengguna & akses'],['audit','Audit'],['archive','Riwayat sebelum migrasi'],['settings','Pengaturan']]:[]),['setup','Persiapan']]]];
 $('#navigation').innerHTML=groups.map(([title,items])=>`<div class="nav-group"><small>${title}</small>${items.map(([id,name])=>`<button data-tab="${id}" ${id===tab?'aria-current="page"':''} ${!catalog.active&&!['setup','kitchens'].includes(id)?'disabled':''}>${name}</button>`).join('')}</div>`).join('');
 $('#identity').innerHTML=`${esc(catalog.user.name)}<br><button data-action="restore-password">Ganti password</button> <button data-action="logout">Keluar</button>`;
 document.body.dataset.theme=inventoryTools.settings.theme||'green';document.body.dataset.density=inventoryTools.settings.density||'normal';
 enhanceForms();
};
function classes(kind){return inventoryTools.classifications.filter(x=>x.kind===kind);}
function classPath(id){const seen=new Set(),names=[];while(id&&!seen.has(Number(id))){seen.add(Number(id));const x=inventoryTools.classifications.find(x=>x.id===Number(id));if(!x)break;names.unshift(x.name);id=x.parent_id;}return names.join(' › ');}
function classOptions(kind){return classes(kind).map(x=>({...x,name:kind==='category'?classPath(x.id):x.name}));}
function descendant(id,ancestor){if(!ancestor)return true;const seen=new Set();while(id&&!seen.has(id)){if(Number(id)===Number(ancestor))return true;seen.add(id);id=inventoryTools.classifications.find(x=>x.id===Number(id))?.parent_id;}return false;}
function productMatch(p){const f=inventoryFilter;return (!f.q||`${p.code} ${p.name}`.toLowerCase().includes(f.q.toLowerCase()))&&descendant(p.category_id,f.category)&&(!f.brand||Number(f.brand)===p.brand_id)&&(!f.type||Number(f.type)===p.type_id);}
function stockFilters(){return `<div class="grid filterbar">${field('Cari produk',input('restore-search',inventoryFilter.q,'search','placeholder="Kode / nama produk"'))}${field('Gudang',select('restore-warehouse',writableWarehouses(),inventoryFilter.warehouse,false))}${field('Kategori',select('restore-category',classOptions('category'),inventoryFilter.category,false))}${field('Merek',select('restore-brand',classOptions('brand'),inventoryFilter.brand,false))}${field('Jenis',select('restore-type',classOptions('type'),inventoryFilter.type,false))}</div>`;}
function expiryWarning(p){let id=p.category_id;const seen=new Set();while(id&&!seen.has(id)){seen.add(id);const x=inventoryTools.classifications.find(x=>x.id===id);if(!x)break;if(x.expWarnDays!=null)return Number(x.expWarnDays);id=x.parent_id;}return Number(inventoryTools.settings.expWarnDays||30);}
function stockSummary(){const groups=new Map();for(const w of catalog.warehouses.filter(w=>w.active&&(catalog.warehouse_access===null||catalog.warehouse_access.includes(w.id))))for(const p of products()){if(!productMatch(p)||inventoryFilter.warehouse&&w.id!==Number(inventoryFilter.warehouse))continue;groups.set(`${w.id}:${p.id}`,{p,w,qty:0,reserved:0,available:0,value:0,expiry:null});}for(const s of stock){const g=groups.get(`${s.warehouse_id}:${s.product_id}`);if(!g)continue;g.qty+=Number(s.qty);g.reserved+=Number(s.reserved_scrap);g.available+=s.usable?Number(s.available_qty):0;g.value+=Number(s.qty)*Number(s.unit_cost);if(s.expiry_date&&(!g.expiry||s.expiry_date<g.expiry))g.expiry=s.expiry_date;}return [...groups.values()].filter(x=>x.qty||Number(x.w.kind==='central'?x.p.min_central:x.p.min_branch)>0);}
function renderDashboard(){const rows=stockSummary(),value=stock.reduce((n,s)=>n+Number(s.qty)*Number(s.unit_cost),0),low=rows.filter(x=>x.available<Number(x.w.kind==='central'?x.p.min_central:x.p.min_branch)),near=stock.filter(s=>s.expiry_date&&Math.ceil((new Date(s.expiry_date)-new Date(localToday()))/86400000)<=expiryWarning(catalog.products.find(p=>p.id===s.product_id))),pending=operations.documents.filter(o=>o.status==='pending');return `<section><h2>Dashboard inventory</h2><p class="muted">${esc(inventoryTools.settings.company)} · ${localToday()} · Sesuai lingkup gudang akun</p><div class="kpis"><div><small>Nilai persediaan</small><strong>${rupiah(value)}</strong></div><div><small>Di bawah minimum</small><strong>${low.length}</strong></div><div><small>Batch mendekati / lewat ED</small><strong>${near.length}</strong></div><div><small>Pengiriman dalam perjalanan</small><strong>${transfers.filter(t=>t.status!=='received').length}</strong></div></div></section><section><h3>Perlu ditindaklanjuti</h3><div class="actions"><button data-tab="purchasing">PO menunggu (${pending.filter(o=>o.kind==='po').length})</button><button data-tab="opname">Opname menunggu (${pending.filter(o=>o.kind==='opname').length})</button><button data-tab="scrap">Scrap menunggu (${pending.filter(o=>o.kind==='scrap').length})</button><button data-tab="forecast">Rekomendasi pembelian</button></div>${table(['Produk','Gudang','Tersedia layak','Minimum'],low.map(x=>`<tr><td>${esc(x.p.name)}</td><td>${esc(x.w.name)}</td><td>${fmt(x.available)} ${esc(x.p.base_uom)}</td><td>${fmt(x.w.kind==='central'?x.p.min_central:x.p.min_branch)}</td></tr>`))}</section><section><h3>Nilai persediaan per gudang</h3>${table(['Gudang','Nilai','Porsi'],catalog.warehouses.map(w=>{const v=stock.filter(s=>s.warehouse_id===w.id).reduce((n,s)=>n+Number(s.qty)*Number(s.unit_cost),0);return v?`<tr><td>${esc(w.name)}</td><td>${rupiah(v)}</td><td><meter min="0" max="${value||1}" value="${v}"></meter> ${fmt(v/(value||1)*100)}%</td></tr>`:''}))}</section>`;}
const oldRenderStock=renderStock;
renderStock=function(){const html=oldRenderStock(),rest=html.slice(html.indexOf('</section>')+10);let body;if(inventoryFilter.view==='summary'){body=table(['Produk / kategori','Gudang','Stok','Ditahan','Layak tersedia','Minimum','Nilai','ED terdekat'],stockSummary().map(x=>`<tr><td><strong>${esc(x.p.code)} · ${esc(x.p.name)}</strong><small>${esc(classPath(x.p.category_id))}</small></td><td>${esc(x.w.name)}</td><td>${fmt(x.qty)} ${esc(x.p.base_uom)}</td><td>${fmt(x.reserved)}</td><td>${fmt(x.available)}</td><td>${fmt(x.w.kind==='central'?x.p.min_central:x.p.min_branch)}</td><td>${rupiah(x.value)}</td><td>${esc(x.expiry||'—')}</td></tr>`));}else body=table(['Produk','Gudang / rak','Batch / masuk','Qty / tersedia','ED','HPP / nilai',''],stock.filter(s=>productMatch(catalog.products.find(p=>p.id===s.product_id))&&(!inventoryFilter.warehouse||s.warehouse_id===Number(inventoryFilter.warehouse))).map(s=>{const p=catalog.products.find(p=>p.id===s.product_id);const near=s.expiry_date&&Math.ceil((new Date(s.expiry_date)-new Date(localToday()))/86400000)<=expiryWarning(p);return `<tr><td>${esc(p.code)} · ${esc(p.name)}</td><td>${esc(nameOf(catalog.warehouses,s.warehouse_id))}<small>Rak ${esc(s.rack||'—')}</small></td><td>${esc(s.batch_number)}<small>${esc(s.received_at)}</small></td><td>${fmt(s.qty)} ${esc(p.base_uom)}<small>Tersedia ${fmt(s.available_qty)}</small></td><td><span class="chip ${near||!s.usable?'warn':''}">${esc(s.expiry_date||'Belum diisi')}</span><small>${s.usable?'Layak':'Diblokir / kedaluwarsa'}</small></td><td>${rupiah(s.unit_cost)}<small>${rupiah(Number(s.qty)*Number(s.unit_cost))}</small></td><td>${canWrite()?`<button data-action="restore-rack" data-id="${s.balance_id}">Atur rak</button>`:''}${isAdmin()&&!s.expiry_date?`<button data-action="correct-lot" data-id="${s.lot_id}">Lengkapi ED</button>`:''}</td></tr>`;}));return `<section><h2>Persediaan</h2>${stockFilters()}<div class="actions"><button data-action="restore-stock-summary">Ringkasan produk</button><button data-action="restore-stock-batches">Per batch / rak</button><a href="/api/manufacturing/report/valuation?export=true">Unduh Excel stok</a></div>${body}</section>${rest}<section id="usage-result"></section>`;};
function enhanceForms(){
 const p=catalog.products.find(p=>p.id===editProduct),f=$('[data-form=product]');
 if(f){f.querySelector('[name=kind]').closest('label').firstChild.textContent='Jenis manufaktur';f.querySelector('.grid').insertAdjacentHTML('beforeend',`${field('Kategori inventory',select('category_id',classOptions('category'),p?.category_id,false))}${field('Merek',select('brand_id',classOptions('brand'),p?.brand_id,false))}${field('Jenis inventory',select('type_id',classOptions('type'),p?.type_id,false))}${field('Supplier utama',select('supplier_id',operations.suppliers,p?.supplier_id,false))}${field('Satuan beli default',input('purchase_uom',p?.purchase_uom||p?.base_uom||'','text','placeholder="Kosong = satuan dasar"'))}${field('Minimum Central',input('min_central',p?.min_central||0,'number','min="0" step="0.000001"'))}${field('Minimum cabang/dapur',input('min_branch',p?.min_branch||0,'number','min="0" step="0.000001"'))}${field('Harga referensi / satuan dasar',input('ref_price',p?.ref_price||0,'number','min="0" step="0.00000001"'))}${field('Reservasi transfer (jam; kosong ikut kategori)',input('reserve_hours',p?.reserve_hours??'','number','min="0"'))}`);}
 const po=$('[data-form=po]');if(po){po.elements.number.required=false;po.elements.number.placeholder='Otomatis saat disimpan';const o=operations.documents.find(o=>o.id===editPo);po.querySelector('.grid').insertAdjacentHTML('beforeend',field('Catatan PO',input('note',o?.data.note||'','text','maxlength="1000"')));po.querySelector('#po-lines').insertAdjacentHTML('afterend','<p id="po-grand-total" class="total"></p>');poPreview(0);}
 const supplier=$('[data-form=supplier]');if(supplier){const s=operations.suppliers.find(s=>s.id===editSupplier);supplier.querySelector('.grid').insertAdjacentHTML('beforeend',field('Lead time default (hari)',input('lead_days',s?.lead_days??3,'number','required min="0"')));}
 const usage=$('[data-form=usage]');if(usage){usage.elements.qty.closest('label').firstChild.textContent='Qty pemakaian';usage.querySelector('.grid').insertAdjacentHTML('beforeend',field('Satuan pemakaian','<select name="uom" required></select>'));usage.insertAdjacentHTML('beforeend','<div id="usage-preview"></div>');updateUsageUnits();}
 const receipt=$('[data-form=receipt]');if(receipt){receipt.querySelector('.grid').insertAdjacentHTML('beforeend',field('Rak',input('rack')));}
 const scrap=$('[data-form=request-scrap]');if(scrap){scrap.elements.number.required=false;scrap.elements.number.placeholder='Otomatis saat disimpan';scrap.elements.reason.setAttribute('list','scrap-reasons');scrap.insertAdjacentHTML('beforeend','<datalist id="scrap-reasons"><option value="Kedaluwarsa"><option value="Rusak"><option value="Terkontaminasi"><option value="Hilang"><option value="Lainnya"></datalist><p id="scrap-total" class="total"></p>');scrapValue();}
 if(tab==='products')$('#content section').insertAdjacentHTML('afterbegin','<div class="actions"><a href="/api/manufacturing/products.xlsx">Ekspor produk Excel</a><a href="/api/manufacturing/products.xlsx?template=true">Template impor</a><label>Impor produk<input type="file" id="restore-product-import" accept=".xlsx,.csv"></label></div>');
 if(tab==='access')enhanceAccounts();
}
function priceSuggestion(p,unit){for(const o of operations.documents){if(o.kind!=='po'||!['approved','partial','received','closed'].includes(o.status))continue;const l=o.data.lines.find(l=>l.product_id===p.id&&poPurchaseUnit(l)===unit);if(l)return {value:l.purchase_price??l.unit_price,source:`Harga terakhir ${o.number}`};}if(p.legacy_prices?.[unit])return p.legacy_prices[unit];return {value:Number(p.ref_price||0)*Number(poUnits(p)[unit]||1),source:'Harga referensi master'};}
poRows=function(){return table(['Produk','Qty beli','Satuan','Harga / satuan','Diskon %','Subtotal net',''],poLines.map((l,i)=>{const p=catalog.products.find(p=>p.id===Number(l.product_id)),unit=l.purchase_uom||p?.purchase_uom||p?.base_uom;return `<tr><td>${select('po-product-'+i,products(),l.product_id)}<small id="po-price-source-${i}">${esc(l.price_source||'')}</small></td><td>${qtyInput('po-qty-'+i,l.qty??'')}</td><td>${p?snapshotUnitSelect('po-uom-'+i,poUnits(p),p.base_uom,unit):`<select name="po-uom-${i}" disabled><option>Pilih produk</option></select>`}<small id="po-conversion-${i}"></small></td><td>${input('po-price-'+i,l.unit_price??'','number','required min="0" step="0.00000001"')}<small id="po-price-label-${i}">Harga per ${esc(unit||'satuan')}</small></td><td>${input('po-discount-'+i,l.discount??0,'number','required min="0" max="100" step="0.01"')}</td><td id="po-subtotal-${i}">${rupiah(Number(l.qty||0)*Number(l.unit_price||0)*(1-Number(l.discount||0)/100))}</td><td><button type="button" data-action="ops-remove-po-line" data-id="${i}">Hapus</button></td></tr>`;}));};
collectPo=function(){const f=$('[data-form=po]');if(!f)return;const d=new FormData(f);poLines=poLines.map((l,i)=>({...l,product_id:Number(d.get('po-product-'+i)),qty:d.get('po-qty-'+i),unit_price:d.get('po-price-'+i),purchase_uom:d.get('po-uom-'+i),discount:d.get('po-discount-'+i)||'0'}));};
poPreview=function(){const f=$('[data-form=po]');if(!f)return;let total=0;poLines.forEach((l,i)=>{const p=catalog.products.find(p=>p.id===Number(f.elements['po-product-'+i]?.value));if(!p)return;const unit=f.elements['po-uom-'+i].value,q=Number(f.elements['po-qty-'+i].value),price=Number(f.elements['po-price-'+i].value),discount=Number(f.elements['po-discount-'+i].value),sub=q*price*(1-discount/100);total+=sub;$('#po-conversion-'+i).textContent=`${fmt(q*Number(poUnits(p)[unit]))} ${p.base_uom}`;$('#po-price-label-'+i).textContent='Harga per '+unit;$('#po-subtotal-'+i).textContent=rupiah(sub);const ref=Number(p.ref_price),net=price*(1-discount/100)/Number(poUnits(p)[unit]);if(ref&&Math.abs((net-ref)/ref*100)>Number(inventoryTools.settings.priceTolerance))$('#po-subtotal-'+i).insertAdjacentHTML('beforeend','<small class="danger">Harga di luar toleransi referensi</small>');});if($('#po-grand-total'))$('#po-grand-total').textContent='Total PO: '+rupiah(total);};
const oldOpAction=operationAction;
operationAction=async function(action,id,button){await oldOpAction(action,id,button);if(action==='ops-edit-po'){const o=operations.documents.find(o=>o.id===id);poLines=poLines.map((l,i)=>({...l,discount:o.data.lines[i].discount||0}));$('#po-lines').innerHTML=poRows();poPreview();}if(action.includes('po-line'))poPreview();};
const oldPrintLineTotal=printLineTotal;
printLineTotal=function(line){return line.line_total!=null?printNumber(line.line_total,true):oldPrintLineTotal(line);};
const oldPoDetail=renderPoDetail;
renderPoDetail=function(o){return oldPoDetail(o).replace('</section>',`<p>Catatan: ${esc(o.data.note||'—')}</p>${table(['Produk','Diskon','Harga net / satuan beli','Subtotal net'],o.data.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${fmt(l.discount||0)}%</td><td>${rupiah(l.net_purchase_price??l.purchase_price??l.unit_price)}</td><td>${rupiah(l.line_total??Number(l.qty)*Number(l.unit_price))}</td></tr>`))}</section>`);};
operationTable=function(kind){const state=operationFilter[kind]||'active';const docs=operations.documents.filter(o=>o.kind===kind&&(state==='all'||(state==='active'?['draft','pending','approved','partial'].includes(o.status):!['draft','pending','approved','partial'].includes(o.status))));return `<div class="actions">${[['active','Berjalan'],['history','Riwayat'],['all','Semua']].map(([v,l])=>`<button data-action="restore-status" data-kind="${kind}" data-value="${v}" ${v===state?'class="primary"':''}>${l}</button>`).join('')}</div>`+table(['Nomor / tanggal','Gudang / supplier','Isi / nilai','Status',''],docs.map(o=>`<tr><td><strong>${esc(o.number)}</strong><small>${esc(o.document_date)}</small></td><td>${esc(nameOf(catalog.warehouses,o.warehouse_id))}<small>${esc(o.data.supplier_name||'')}</small></td><td>${o.data.lines.length} baris${o.data.total!=null?`<small>${rupiah(o.data.total)}</small>`:''}</td><td><span class="chip ${o.status==='pending'?'warn':''}">${esc(operationLabels[o.status]||o.status)}</span></td><td><button data-action="ops-open" data-id="${o.id}">Buka</button>${kind==='po'&&printablePo(o)?` <button data-action="ops-print-po" data-id="${o.id}">Cetak</button>`:''}</td></tr>`));};
function updateUsageUnits(){const f=$('[data-form=usage]');if(!f)return;const p=catalog.products.find(p=>p.id===Number(f.elements.product_id.value));f.elements.uom.innerHTML=p?Object.keys(poUnits(p)).map(u=>`<option>${esc(u)}</option>`).join(''):'';usagePreview();}
function usagePreview(){const f=$('[data-form=usage]'),out=$('#usage-preview');if(!f||!out)return;const p=catalog.products.find(p=>p.id===Number(f.elements.product_id.value));if(!p){out.innerHTML='';return;}let need=Number(f.elements.qty.value)*Number(poUnits(p)[f.elements.uom.value]||1),cost=0;const picks=[];for(const s of stock.filter(s=>s.product_id===p.id&&s.warehouse_id===Number(f.elements.warehouse_id.value)&&s.usable)){const q=Math.min(need,Number(s.available_qty));if(q>0){picks.push({...s,take:q});cost+=q*Number(s.unit_cost);need-=q;}}out.innerHTML=table(['Batch','ED','Qty dipakai','HPP','Nilai'],picks.map(s=>`<tr><td>${esc(s.batch_number)}</td><td>${s.expiry_date}</td><td>${fmt(s.take)} ${esc(p.base_uom)}</td><td>${rupiah(s.unit_cost)}</td><td>${rupiah(s.take*Number(s.unit_cost))}</td></tr>`))+`<p>Estimasi HPP: <strong>${rupiah(cost)}</strong>${need>0?` · <span class="danger">Stok kurang ${fmt(need)} ${esc(p.base_uom)}</span>`:''}</p><small>Alokasi akhir diverifikasi ulang saat penyimpanan.</small>`;}
function scrapValue(){const f=$('[data-form=request-scrap]');if(!f)return;let total=0;scrapLines.forEach((l,i)=>{const s=stock.find(s=>s.balance_id===Number(f.elements['scrap-balance-'+i]?.value));total+=Number(s?.unit_cost||0)*Number(f.elements['scrap-qty-'+i]?.value||0);});if($('#scrap-total'))$('#scrap-total').textContent='Estimasi kerugian: '+rupiah(total);}
const countPending=new Map();let countTimer=null,countChain=Promise.resolve(),countError=null;
function queueCount(){const f=$('[data-form=opname-count]');if(!f)return;const o=operations.documents.find(o=>o.id===Number(f.dataset.id));if(o?.status!=='draft')return;const d=new FormData(f);countPending.set(o.id,{token:o.data.token,counted_by:d.get('counted_by')||'',reason:d.get('reason')||'',lines:o.data.lines.map(l=>({balance_id:l.balance_id,counted_qty:d.get('count-'+l.balance_id)}))});if($('#count-save-state'))$('#count-save-state').textContent='Menyimpan…';clearTimeout(countTimer);countTimer=setTimeout(()=>flushCounts().catch(e=>message(e.message,true)),600);}
function flushCounts(){clearTimeout(countTimer);countChain=countChain.catch(()=>{}).then(async()=>{for(const [id,data] of [...countPending]){const o=operations.documents.find(o=>o.id===id);try{const saved=await command('save-count',{id,revision:o.revision,...data});operations.documents[operations.documents.findIndex(o=>o.id===id)]=saved;if(countPending.get(id)===data)countPending.delete(id);countError=null;if($('#count-save-state'))$('#count-save-state').textContent='Tersimpan di server';}catch(e){countError=e;throw e;}}});return countChain;}
renderOpname=function(){const o=operations.documents.find(o=>o.id===selectedOperation&&o.kind==='opname'),counting=o?.status==='draft'&&canWrite(),showVariance=o&&o.status!=='draft'&&(canApprove()||o.status==='posted'),completed=o?.data.lines.filter(l=>l.counted_qty!=null&&l.counted_qty!=='').length||0;return `<section><h2>Stock opname</h2><p class="muted">Hitung fisik tanpa menampilkan saldo sistem. Pilih seluruh gudang atau satu rak. Hasil hitung disimpan bertahap; persetujuan memposting selisih terhadap snapshot.</p>${operationTable('opname')}</section>${o?`<section>${operationHeader(o)}<p>Lokasi: ${esc(o.data.rack||'Seluruh gudang')} · Terisi ${completed} / ${o.data.lines.length} · Hitung ulang ${o.data.recount||0}</p>${counting?`<div class="actions"><a href="/api/manufacturing/opname/${o.id}/template">Unduh template Excel</a><label>Unggah hasil hitung<input id="restore-count-import" type="file" accept=".xlsx" data-id="${o.id}"></label><button data-action="restore-save-count">Simpan sementara</button><span id="count-save-state">${o.data.saved_at?'Tersimpan '+esc(o.data.saved_at):'Belum ada hitungan tersimpan'}</span></div>`:''}${o.status==='pending'&&canApprove()?`<button data-action="restore-recount" data-id="${o.id}">Minta hitung ulang</button>`:''}<form data-form="opname-count" data-id="${o.id}">${table(['Barang / batch','Rak','Satuan',...(showVariance?['Saldo snapshot']:[]),'Qty fisik',...(showVariance?['Selisih qty','Selisih nilai']:[])],o.data.lines.map(l=>`<tr><td>${esc(l.code)} · ${esc(l.name)}<small>${esc(l.batch_number)}</small></td><td>${esc(l.rack||'—')}</td><td>${esc(l.uom)}</td>${showVariance?`<td>${fmt(l.system_qty)}</td>`:''}<td>${counting?input('count-'+l.balance_id,l.counted_qty??'','number','required min="0" step="0.000001"'):esc(l.counted_qty??'Belum dihitung')}</td>${showVariance?`<td>${fmt(l.difference)}</td><td>${rupiah(Number(l.difference)*Number(l.unit_cost))}</td>`:''}</tr>`))}${showVariance?`<p class="total">Total selisih nilai: ${rupiah(o.data.lines.reduce((n,l)=>n+Number(l.difference||0)*Number(l.unit_cost||0),0))}</p>`:''}${counting?`<h3>Lot ditemukan yang belum tercatat</h3><div id="opname-extras">${extraRows()}</div><button type="button" data-action="ops-add-extra">Tambah lot temuan</button><div class="grid">${field('Petugas penghitung',input('counted_by',o.data.counted_by||catalog.user.name,'text','required maxlength="150"'))}${field('Catatan / alasan selisih',input('reason',o.data.reason||'','text','required maxlength="500"'))}</div><button class="primary">Ajukan hasil opname</button>`:''}</form></section>`:''}${canWrite()?`<section><h3>Mulai sesi hitung</h3><form data-form="start-opname"><div class="grid">${field('Nomor opname',input('number','','text','placeholder="Otomatis saat disimpan" maxlength="100"'))}${field('Tanggal dokumen',input('document_date',localToday(),'date',`required max="${localToday()}"`))}${field('Gudang',select('warehouse_id',writableWarehouses()))}${field('Rak (kosong = seluruh gudang)',input('rack','','text','maxlength="50" list="rack-list"'))}<datalist id="rack-list">${[...new Set(stock.map(s=>s.rack).filter(Boolean))].map(r=>`<option value="${esc(r)}">`).join('')}</datalist></div><button class="primary">Mulai hitung</button></form></section>`:''}`;};
function renderClassification(){const row=inventoryTools.classifications.find(x=>x.id===classEdit);return `<section><h2>Kategori, merek & jenis inventory</h2><p class="muted">Klasifikasi ini terpisah dari jenis manufaktur produk. Kategori dapat memiliki tiga tingkat.</p>${table(['Kelompok','Nama / hierarki','Status',''],inventoryTools.classifications.map(x=>`<tr><td>${esc({category:'Kategori',brand:'Merek',type:'Jenis'}[x.kind])}</td><td>${esc(x.kind==='category'?classPath(x.id):x.name)}</td><td>${x.active?'Aktif':'Nonaktif'}</td><td>${isAdmin()?`<button data-action="restore-edit-class" data-id="${x.id}">Ubah</button>`:''}</td></tr>`))}</section>${isAdmin()?`<section><h3>${row?'Ubah':'Tambah'} klasifikasi</h3><form data-form="restore-class"><div class="grid">${field('Kelompok',`<select name="kind">${['category','brand','type'].map(k=>`<option value="${k}" ${row?.kind===k?'selected':''}>${{category:'Kategori',brand:'Merek',type:'Jenis'}[k]}</option>`).join('')}</select>`)}${field('Nama',input('name',row?.name,'text','required maxlength="150"'))}${field('Induk kategori',select('parent_id',classOptions('category').filter(x=>x.id!==row?.id),row?.parent_id,false))}${field('Peringatan ED (hari; kosong ikut induk)',input('expWarnDays',row?.expWarnDays??'','number','min="0"'))}${field('Reservasi (jam; kosong ikut induk)',input('reserveHours',row?.reserveHours??'','number','min="0"'))}</div><label><input name="active" type="checkbox" ${row?.active!==false?'checked':''}> Aktif</label><div class="actions"><button class="primary">Simpan</button><button type="button" data-action="restore-new-class">Bersihkan</button></div></form></section>`:''}`;}
function renderSettings(){const s=inventoryTools.settings;return `<section><h2>Pengaturan inventory</h2><form data-form="restore-settings"><div class="grid">${field('Nama perusahaan',input('company',s.company,'text','required maxlength="200"'))}${[['expWarnDays','Peringatan ED (hari)'],['priceTolerance','Toleransi harga (%)'],['safetyDays','Safety stock (hari)'],['coverDays','Cakupan stok (hari)'],['usageDays','Periode pemakaian (hari)'],['reserveHours','Reservasi transfer (jam)']].map(([k,l])=>field(l,input(k,s[k],'number','required min="0"'))).join('')}${field('Tema',`<select name="theme">${['green','blue','brown'].map(t=>`<option ${t===s.theme?'selected':''}>${t}</option>`).join('')}</select>`)}${field('Kepadatan',`<select name="density">${['normal','compact'].map(t=>`<option ${t===s.density?'selected':''}>${t}</option>`).join('')}</select>`)}</div><button class="primary">Simpan pengaturan</button></form></section>`;}
const reportNames={valuation:'Valuasi stok',card:'Kartu stok',usage:'HPP pemakaian',anomaly:'Anomali harga',scrap:'Scrap & selisih',expiry:'Batch & kedaluwarsa'};
function reportUrl(){return `/api/manufacturing/report/${reportKind}?days=${reportDays}${reportWarehouse?'&warehouse_id='+Number(reportWarehouse):''}${reportProduct?'&product_id='+Number(reportProduct):''}`;}
function renderReports(){if(reportCache===null){reportCache=[];api(reportUrl()).then(r=>{reportCache=r;if(tab==='reports')render();}).catch(e=>message(e.message,true));}const rows=reportCache,heads=rows.length?Object.keys(rows[0]):[];return `<section><h2>Laporan inventory</h2><div class="actions">${Object.entries(reportNames).map(([k,n])=>`<button data-action="restore-report" data-value="${k}" ${k===reportKind?'class="primary"':''}>${n}</button>`).join('')}</div><div class="grid">${field('Gudang',select('report-warehouse',writableWarehouses(),reportWarehouse,false))}${field('Produk',select('report-product',catalog.products,reportProduct,false))}${field('Periode hari',input('report-days',reportDays,'number','min="1" max="3660"'))}</div><a href="${reportUrl()}&export=true">Unduh Excel</a><p>${rows.length} baris · Nilai total ${rupiah(rows.reduce((s,r)=>s+Number(r.Nilai||0),0))}</p>${table(heads,rows.map(r=>`<tr>${heads.map(h=>`<td>${esc(['Nilai','HPP','Referensi'].includes(h)?rupiah(r[h]):r[h])}</td>`).join('')}</tr>`))}</section>`;}
function renderForecast(){if(forecastCache===null){forecastCache=[];api('/api/manufacturing/forecast').then(r=>{forecastCache=r;if(tab==='forecast')render();}).catch(e=>message(e.message,true));}return `<section><h2>Forecast pembelian</h2><p class="muted">Pemakaian rata-rata, lead time aktual/default, safety stock dan cakupan stok mengikuti pengaturan. Hanya stok layak yang dihitung tersedia. Qty rekomendasi dibulatkan ke satuan beli.</p>${table(['Pilih','Produk / supplier','Pemakaian/hari','Lead time','Tersedia / dipesan','ROP / target','Rekomendasi','Status'],forecastCache.map(r=>`<tr><td><input type="checkbox" name="forecast-pick" value="${r.product_id}" ${!r.supplier_id||Number(r.qty)<=0?'disabled':''}></td><td>${esc(r.code)} · ${esc(r.name)}<small>${esc(r.supplier_name)}</small></td><td>${fmt(r.daily)} ${esc(r.base_uom)}</td><td>${fmt(r.lead_days)} hari</td><td>${fmt(r.onhand)} / ${fmt(r.onorder)}</td><td>${fmt(r.rop)} / ${fmt(r.target)}</td><td>${fmt(r.qty)} ${esc(r.purchase_uom)}</td><td>${esc(r.status)}</td></tr>`))}${canPurchase()?`<div class="grid">${field('Gudang penerima PO',select('forecast-warehouse',writableWarehouses().filter(w=>w.kind==='central')))}</div><button data-action="restore-forecast-po" class="primary">Buat draft PO per supplier dari pilihan</button>`:''}</section>`;}
function renderAudit(){if(auditCache===null){auditCache=[];(async()=>{let last=0;while(true){const rows=await api('/api/manufacturing/audit?after='+last+'&limit=1000');auditCache.push(...rows);if(rows.length<1000)break;last=rows.at(-1).id;}if(tab==='audit')render();})().catch(e=>message(e.message,true));}return `<section><h2>Audit transaksi</h2><div class="actions">${input('audit-search','','search','placeholder="Cari aksi / pengguna / dokumen"')}<button data-action="restore-export-audit">Unduh JSON Lines</button></div><div id="audit-rows">${auditTable(auditCache)}</div></section>`;}
function auditTable(rows){return table(['Waktu','Pengguna','Aksi','Rincian'],[...rows].reverse().map(a=>`<tr><td>${esc(a.at)}</td><td>${esc(a.actor)}</td><td>${esc(a.operation)}</td><td><details><summary>Lihat data</summary><pre>${esc(JSON.stringify(a.data,null,2))}</pre></details></td></tr>`));}
function renderArchive(){if(archiveCache===null){archiveCache={};api('/api/manufacturing/archive').then(r=>{archiveCache=r.data||{};if(tab==='archive')render();}).catch(e=>message(e.message,true));}return `<section><h2>Riwayat sebelum migrasi</h2><p>Dokumen sumber tetap dapat ditelusuri. Saldo berjalan menggunakan pencatatan fondasi; arsip ini tidak memposting ulang transaksi.</p><button data-action="archive">Unduh seluruh arsip</button>${['pos','inbounds','transfers','usages','scraps','opnames','movements','audit'].map(k=>`<details><summary>${esc({pos:'PO',inbounds:'Penerimaan',transfers:'Transfer',usages:'Pemakaian',scraps:'Scrap',opnames:'Opname',movements:'Mutasi',audit:'Audit'}[k])} (${archiveCache[k]?.length||0})</summary>${table(['Dokumen / waktu','Status','Rincian'],(archiveCache[k]||[]).map(d=>`<tr><td>${esc(d.no||d.ref||d.id||'')}<small>${esc(d.createdAt||d.ts||d.timestamp||'')}</small></td><td>${esc(d.status||d.type||d.action||'')}</td><td><details><summary>Buka</summary><pre>${esc(JSON.stringify(d,null,2))}</pre></details></td></tr>`))}</details>`).join('')}</section>`;}
function enhanceAccounts(){const section=$('#content section');section.insertAdjacentHTML('beforeend',table(['Akun','Status','Pengelolaan'],users.map(u=>`<tr><td>${esc(u.name)} · ${esc(u.username)}</td><td>${u.isActive?'Aktif':'Nonaktif'}</td><td><button data-action="restore-edit-user" data-id="${u.id}">Ubah / reset password</button> <button data-action="restore-toggle-user" data-id="${u.id}">${u.isActive?'Nonaktifkan':'Aktifkan'}</button></td></tr>`)));}
function downloadText(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function fileBase64(file){return new Promise((resolve,reject)=>{if(file.size>3000000){reject(Error('File maksimal 3 MB.'));return;}const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=()=>reject(Error('Tidak dapat membaca file'));r.readAsDataURL(file);});}
// Intercept only the restored controls; all existing manufacturing handlers remain active.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const action=b.dataset.action||'';
 if(countPending.size&&(b.dataset.tab||action.startsWith('ops-'))){e.preventDefault();e.stopImmediatePropagation();flushCounts().then(()=>b.click()).catch(err=>message('Hitungan belum tersimpan: '+err.message,true));return;}
 if(!action.startsWith('restore-')||action.startsWith('restore-in-')||action.startsWith('restore-transfer-'))return;e.preventDefault();e.stopImmediatePropagation();
 task(async()=>{const id=Number(b.dataset.id);
 if(action==='restore-status'){operationFilter[b.dataset.kind]=b.dataset.value;render();return;}
 if(action.startsWith('restore-stock-')){inventoryFilter.view=action.endsWith('batches')?'batches':'summary';render();return;}
 if(action==='restore-edit-class'||action==='restore-new-class'){classEdit=id||null;render();return;}
 if(action==='restore-save-count'){queueCount();await flushCounts();message('Hitungan tersimpan.');return;}
 if(action==='restore-recount'){const reason=prompt('Alasan hitung ulang:');if(!reason)return;const o=operations.documents.find(o=>o.id===id);await command('recount-opname',{id,revision:o.revision,reason},b);}
 if(action==='restore-rack'){const s=stock.find(s=>s.balance_id===id),rack=prompt('Rak penyimpanan:',s.rack||'');if(rack===null)return;await command('set-rack',{balance_id:id,rack},b);}
 if(action==='restore-report'){reportKind=b.dataset.value;reportCache=null;render();return;}
 if(action==='restore-export-audit'){downloadText('audit-inventory.jsonl',auditCache.map(r=>JSON.stringify(r)).join('\n'));return;}
 if(action==='restore-forecast-po'){const ids=[...document.querySelectorAll('[name=forecast-pick]:checked')].map(x=>Number(x.value)),wh=Number($('[name=forecast-warehouse]').value);if(!ids.length||!wh)throw Error('Pilih produk dan gudang penerima.');const grouped=new Map();for(const r of forecastCache.filter(r=>ids.includes(r.product_id))){if(!grouped.has(r.supplier_id))grouped.set(r.supplier_id,[]);const p=catalog.products.find(p=>p.id===r.product_id);grouped.get(r.supplier_id).push({product_id:r.product_id,qty:r.qty,purchase_uom:r.purchase_uom,unit_price:priceSuggestion(p,r.purchase_uom).value});}for(const [supplier_id,lines] of grouped)await command('save-po',{document_date:localToday(),warehouse_id:wh,supplier_id,lines,note:'Dari rekomendasi forecast'},b);tab='purchasing';}
 if(action==='restore-password'){openDialog('Ganti password',`<form data-form="restore-password">${field('Password saat ini',input('old','','password','required autocomplete="current-password"'))}${field('Password baru',input('new','','password','required minlength="8" autocomplete="new-password"'))}${field('Ulangi password baru',input('repeat','','password','required autocomplete="new-password"'))}<button class="primary">Simpan password</button></form>`);return;}
 if(action==='restore-edit-user'){const u=users.find(u=>u.id===id);openDialog('Ubah pengguna',`<form data-form="restore-user" data-id="${id}">${field('Nama',input('name',u.name,'text','required'))}${field('Peran',`<select name="role">${['admin','gudang','purchasing','approver'].map(r=>`<option ${u.role===r?'selected':''}>${r}</option>`).join('')}</select>`)}${field('Reset password (opsional)',input('password','','password','autocomplete="new-password"'))}<p>Akses gudang dikelola melalui daftar akses tambahan.</p><button class="primary">Simpan</button></form>`);return;}
 if(action==='restore-toggle-user'){const u=users.find(u=>u.id===id);if(!confirm(`${u.isActive?'Nonaktifkan':'Aktifkan'} ${u.name}?`))return;await userPut(id,{isActive:!u.isActive});}
 await refresh();reportCache=forecastCache=auditCache=null;render();message('Tersimpan di server.');
 });
},true);
function openDialog(title,content){$('#restore-dialog')?.remove();const d=document.createElement('dialog');d.id='restore-dialog';d.innerHTML=`<h2>${esc(title)}</h2>${content}<button type="button" id="close-restore-dialog">Tutup</button>`;document.body.appendChild(d);d.querySelector('#close-restore-dialog').onclick=()=>d.close();d.showModal();}
async function userPut(id,body){const r=await fetch('/api/users/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.detail);return data;}
document.addEventListener('input',e=>{if(e.target.closest('[data-form=opname-count]'))queueCount();if(e.target.closest('[data-form=po]'))poPreview();if(e.target.closest('[data-form=usage]'))usagePreview();if(e.target.closest('[data-form=request-scrap]'))scrapValue();if(e.target.name==='audit-search')$('#audit-rows').innerHTML=auditTable(auditCache.filter(a=>JSON.stringify(a).toLowerCase().includes(e.target.value.toLowerCase())));});
document.addEventListener('change',e=>{
 const name=e.target.name||'';
 if(name.startsWith('restore-')&&['search','warehouse','category','brand','type'].includes(name.slice(8))){inventoryFilter[name==='restore-search'?'q':name.slice(8)]=e.target.value;render();}
 if(name.startsWith('report-')){if(name==='report-warehouse')reportWarehouse=e.target.value;if(name==='report-product')reportProduct=e.target.value;if(name==='report-days')reportDays=Math.max(1,Math.min(3660,Number(e.target.value)||30));reportCache=null;render();}
 if(e.target.closest('[data-form=usage]')){if(name==='product_id')updateUsageUnits();else usagePreview();}
 if(name.startsWith('po-product-')||name.startsWith('po-uom-')){const i=Number(name.split('-').at(-1));collectPo();const p=catalog.products.find(p=>p.id===poLines[i].product_id);if(p){if(name.startsWith('po-product-'))poLines[i].purchase_uom=p.purchase_uom||p.base_uom;const price=priceSuggestion(p,poLines[i].purchase_uom);poLines[i].unit_price=price.value;poLines[i].price_source=price.source;const f=$('[data-form=po]');if(!f.elements.supplier_id.value&&p.supplier_id)f.elements.supplier_id.value=p.supplier_id;$('#po-lines').innerHTML=poRows();poPreview();}}
 if(e.target.id==='restore-count-import')task(async()=>{await flushCounts();const o=operations.documents.find(o=>o.id===Number(e.target.dataset.id)),file=e.target.files[0];if(!file)return;const r=await command('import-count',{id:o.id,revision:o.revision,file:await fileBase64(file)});await refresh();render();message(`${r.imported} baris tersimpan.${r.errors.length?'\n'+r.errors.join('\n'):''}`,!!r.errors.length);});
 if(e.target.id==='restore-product-import')task(async()=>{const file=e.target.files[0];if(!file)return;const r=await command('import-products',{file:await fileBase64(file),preview:true});openDialog('Pratinjau impor produk',`<p>${r.rows.length} baris valid. ${r.errors.length} kesalahan.</p><pre>${esc(r.errors.join('\n'))}</pre>${table(['Kode','Nama','Tindakan'],r.rows.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.name)}</td><td>${x.id?'Perbarui':'Tambah'}</td></tr>`))}<button id="confirm-product-import" ${r.errors.length?'disabled':''}>Simpan impor</button>`);$('#confirm-product-import').onclick=()=>task(async()=>{await command('import-products',{file:await fileBase64(file),preview:false});$('#restore-dialog').close();await refresh();render();message('Impor tersimpan.');});});
});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-form]');if(!form)return;const kind=form.dataset.form;
 if(kind==='opname-count'&&countPending.size){e.preventDefault();e.stopImmediatePropagation();flushCounts().then(()=>form.requestSubmit()).catch(err=>message(err.message,true));return;}
 if(!kind.startsWith('restore-')||kind==='restore-receipt')return;e.preventDefault();e.stopImmediatePropagation();task(async()=>{const body=Object.fromEntries(new FormData(form));
 if(kind==='restore-class'){if(classEdit){const x=inventoryTools.classifications.find(x=>x.id===classEdit);body.id=x.id;body.revision=x.revision;}body.active=form.elements.active.checked;await command('save-classification',body,form);classEdit=null;}
 if(kind==='restore-settings')await command('save-settings',body,form);
 if(kind==='restore-user'){if(!body.password)delete body.password;await userPut(Number(form.dataset.id),body);$('#restore-dialog').close();}
 if(kind==='restore-password'){if(body.new!==body.repeat)throw Error('Ulangan password tidak sama.');await api('/api/auth/password',{old:body.old,new:body.new});$('#restore-dialog').close();}
 await refresh();render();message('Tersimpan di server.');});
},true);
window.addEventListener('beforeunload',e=>{if(countPending.size){e.preventDefault();e.returnValue='';}});

task(async()=>{await refresh();tab=catalog.active?'dashboard':'setup';render();});
let inboundLines=[{}],inboundPo=null;
const renderBeforeReceiving=render;
render=function(){if(tab==='receiving'){const prior=tab;tab='stock';renderBeforeReceiving();tab=prior;$('#content').innerHTML=renderReceiving();$('#navigation [data-tab=stock]')?.removeAttribute('aria-current');}else renderBeforeReceiving();$('#navigation .nav-group:nth-child(2)').insertAdjacentHTML('afterbegin',`<button data-tab="receiving" ${tab==='receiving'?'aria-current="page"':''}>Penerimaan pembelian</button>`);};
function collectInbound(){const f=$('[data-form=restore-receipt]');if(!f)return;const d=new FormData(f);inboundLines=inboundLines.map((l,i)=>({...l,product_id:Number(d.get('in-product-'+i)),qty:d.get('in-qty-'+i),uom:d.get('in-uom-'+i),unit_cost:d.get('in-cost-'+i),batch_number:d.get('in-batch-'+i),expiry_date:d.get('in-expiry-'+i),rack:d.get('in-rack-'+i)}));}
function inboundRows(){const o=operations.documents.find(o=>o.id===inboundPo);return table(['Produk','Qty / satuan','Harga per satuan','Batch / ED','Rak',''],inboundLines.map((l,i)=>{const p=catalog.products.find(p=>p.id===Number(l.product_id)),pol=o?.data.lines.find(x=>x.product_id===p?.id),units=pol?{[pol.uom]:'1',[poPurchaseUnit(pol)]:pol.conversion_factor||'1'}:poUnits(p);return `<tr><td>${select('in-product-'+i,o?products().filter(p=>o.data.lines.some(l=>l.product_id===p.id)):products(),l.product_id)}${pol?`<small>Sisa ${fmt(Number(pol.qty)-Number(pol.received_qty))} ${esc(pol.uom)}</small>`:''}</td><td>${qtyInput('in-qty-'+i,l.qty??'')}${snapshotUnitSelect('in-uom-'+i,units,p?.base_uom,l.uom||p?.purchase_uom||p?.base_uom)}</td><td>${input('in-cost-'+i,l.unit_cost??'','number',`required min="0" step="0.00000001" ${o?'readonly':''}`)}</td><td>${input('in-batch-'+i,l.batch_number||'','text','required placeholder="Batch pemasok" maxlength="100"')}${input('in-expiry-'+i,l.expiry_date||'','date','required')}</td><td>${input('in-rack-'+i,l.rack||'','text','maxlength="50"')}</td><td><button type="button" data-action="restore-in-remove" data-id="${i}">Hapus</button></td></tr>`;}));}
function renderReceiving(){const o=operations.documents.find(o=>o.id===inboundPo),available=operations.documents.filter(o=>o.kind==='po'&&['approved','partial'].includes(o.status));const receipts=operations.documents.filter(o=>o.kind==='receipt');return `<section><h2>Penerimaan pembelian</h2><p class="muted">Satu dokumen dapat memuat banyak barang dan beberapa batch untuk produk yang sama. Satuan, harga, ED, dan rak dicatat per baris.</p>${field('Sumber penerimaan',`<select id="restore-inbound-po"><option value="">Tanpa PO / penerimaan langsung</option>${available.map(o=>`<option value="${o.id}" ${inboundPo===o.id?'selected':''}>${esc(o.number)} · ${esc(o.data.supplier_name)}</option>`).join('')}</select>`)}</section>${canWrite()?`<section><form data-form="restore-receipt"><div class="grid">${field('Nomor GRN (langsung)',input('number','','text','placeholder="Otomatis saat disimpan" maxlength="100"'))}${field('Tanggal terima',input('received_date',localToday(),'date',`required max="${localToday()}"`))}${field('Supplier',select('supplier_id',operations.suppliers.filter(s=>s.active),o?.supplier_id))}${field('Gudang Central',select('warehouse_id',writableWarehouses().filter(w=>w.kind==='central'),o?.warehouse_id))}${field('Surat jalan supplier',input('reference','','text','required maxlength="100"'))}${field('Petugas penerima',input('receiver_name',catalog.user.name,'text','required maxlength="150"'))}</div><div id="inbound-lines">${inboundRows()}</div><button type="button" data-action="restore-in-add">Tambah barang / batch</button><div id="inbound-preview"></div><div class="actions"><button class="primary">Simpan penerimaan</button></div></form></section>`:''}<section><h3>Riwayat penerimaan langsung</h3>${table(['Dokumen / tanggal','Supplier / surat jalan','Petugas','Nilai','Rincian'],receipts.map(r=>`<tr><td>${esc(r.number)}<small>${esc(r.document_date)}</small></td><td>${esc(r.data.supplier_name)}<small>${esc(r.data.reference)}</small></td><td>${esc(r.data.receiver_name)}</td><td>${rupiah(r.data.total)}</td><td><details><summary>${r.data.lines.length} baris</summary>${table(['Produk','Batch / ED','Qty','Rak','HPP dasar'],r.data.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${esc(l.batch_number)} / ${esc(l.expiry_date)}</td><td>${fmt(l.input_qty)} ${esc(l.input_uom)}<small>${fmt(l.qty)} ${esc(l.uom)}</small></td><td>${esc(l.rack)}</td><td>${rupiah(l.unit_cost)}</td></tr>`))}</details></td></tr>`))}<h3>Penerimaan dari PO</h3>${table(['PO / tanggal terima','Supplier / surat jalan','Petugas','Rincian'],operations.documents.filter(o=>o.kind==='po').flatMap(o=>o.data.receipts.map(r=>`<tr><td>${esc(o.number)}<small>${esc(r.received_date)}</small></td><td>${esc(o.data.supplier_name)}<small>${esc(r.reference)}</small></td><td>${esc(r.receiver_name)}</td><td>${r.lines.map(l=>`${esc(l.name)} · ${esc(l.batch_number)} · ${fmt(l.receipt_qty||l.qty)} ${esc(l.receipt_uom||l.uom)} · Rak ${esc(l.rack||'—')}`).join('<br>')}</td></tr>`)))}</section>`;}
function inboundPreview(){const f=$('[data-form=restore-receipt]');if(!f)return;collectInbound();let total=0;const notes=[];for(const l of inboundLines){const p=catalog.products.find(p=>p.id===l.product_id);if(!p)continue;const o=operations.documents.find(o=>o.id===inboundPo),pol=o?.data.lines.find(x=>x.product_id===p.id),factor=pol?(l.uom===pol.uom?1:Number(pol.conversion_factor||1)):Number(poUnits(p)[l.uom]||1);total+=Number(l.qty)*Number(l.unit_cost);const ref=Number(p.ref_price);if(ref&&Math.abs((Number(l.unit_cost)/factor-ref)/ref*100)>Number(inventoryTools.settings.priceTolerance))notes.push(`${p.name}: harga berbeda dari referensi di luar toleransi.`);if(l.expiry_date&&Math.ceil((new Date(l.expiry_date)-new Date(localToday()))/86400000)<=expiryWarning(p))notes.push(`${p.name}: batch mendekati / lewat kedaluwarsa.`);}$('#inbound-preview').innerHTML=`<p class="total">Total penerimaan: ${rupiah(total)}</p>${notes.length?`<p class="notice">${notes.map(esc).join('<br>')}</p>`:''}`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action^=restore-in-]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();collectInbound();if(b.dataset.action==='restore-in-add')inboundLines.push({});else inboundLines.splice(Number(b.dataset.id),1);$('#inbound-lines').innerHTML=inboundRows();inboundPreview();},true);
document.addEventListener('change',e=>{if(e.target.id==='restore-inbound-po'){inboundPo=Number(e.target.value)||null;const o=operations.documents.find(o=>o.id===inboundPo);inboundLines=o?o.data.lines.filter(l=>Number(l.qty)>Number(l.received_qty)).map(l=>({product_id:l.product_id,qty:(Number(l.qty)-Number(l.received_qty))/Number(l.conversion_factor||1),uom:poPurchaseUnit(l),unit_cost:l.net_purchase_price??l.purchase_price??l.unit_price})):[{}];render();return;}if(e.target.name?.startsWith('in-product-')||e.target.name?.startsWith('in-uom-')){collectInbound();const i=Number(e.target.name.split('-').at(-1)),p=catalog.products.find(p=>p.id===inboundLines[i].product_id),o=operations.documents.find(o=>o.id===inboundPo),l=o?.data.lines.find(l=>l.product_id===p?.id);if(e.target.name.startsWith('in-product-'))inboundLines[i].uom=l?poPurchaseUnit(l):p?.purchase_uom||p?.base_uom;if(p)inboundLines[i].unit_cost=l?(inboundLines[i].uom===l.uom?l.unit_price:l.net_purchase_price??l.purchase_price):priceSuggestion(p,inboundLines[i].uom).value;$('#inbound-lines').innerHTML=inboundRows();inboundPreview();}});
document.addEventListener('input',e=>{if(e.target.closest('[data-form=restore-receipt]'))inboundPreview();});
document.addEventListener('submit',e=>{const f=e.target.closest('[data-form=restore-receipt]');if(!f)return;e.preventDefault();e.stopImmediatePropagation();task(async()=>{collectInbound();const body=Object.fromEntries(new FormData(f));if(inboundPo){const o=operations.documents.find(o=>o.id===inboundPo);if(Number(body.supplier_id)!==o.supplier_id||Number(body.warehouse_id)!==o.warehouse_id)throw Error('Supplier dan gudang harus sesuai PO.');await command('receive-po',{...body,id:o.id,revision:o.revision,lines:inboundLines},f);}else await command('receive-document',{...body,document_date:body.received_date,lines:inboundLines},f);inboundLines=[{}];inboundPo=null;await refresh();render();message('Penerimaan tersimpan.');});},true);
const renderBeforeTransfer=render;
render=function(){renderBeforeTransfer();if(tab==='transfers'){
 const f=$('[data-form=ship]');if(f){f.elements.document_number.required=false;f.elements.document_number.placeholder='Otomatis saat disimpan';f.insertAdjacentHTML('beforeend','<div class="actions"><button type="button" data-action="restore-transfer-preview">Pratinjau batch FEFO</button><button type="button" data-action="restore-transfer-draft">Simpan draft & reservasi</button></div><div id="transfer-plan"></div>');}
 const docs=operations.documents.filter(o=>o.kind==='transfer');$('#content').insertAdjacentHTML('beforeend',`<section><h3>Draft transfer & reservasi</h3>${table(['Dokumen / tujuan','Reservasi sampai','Status','Batch / nilai',''],docs.map(o=>{const expired=new Date(o.data.expires_at+'Z')<=new Date(),active=o.status==='draft'&&!expired;return `<tr><td>${esc(o.number)}<small>${esc(nameOf(catalog.warehouses,o.data.destination_id))}</small></td><td>${esc(o.data.expires_at)} UTC</td><td>${expired&&o.status==='draft'?'Kedaluwarsa':esc(operationLabels[o.status]||o.status)}</td><td>${o.data.lines.map(l=>`${esc(l.name)} · ${esc(l.batch_number)} · ${fmt(l.qty)} ${esc(l.uom)}`).join('<br>')}<small>${rupiah(o.data.total)}</small></td><td>${active&&canWrite()?`<button data-action="restore-transfer-dispatch" data-id="${o.id}">Kirim draft</button>`:''}${o.status==='draft'&&canWrite()?`<button data-action="ops-cancel-operation" data-id="${o.id}">Batalkan</button>`:''}</td></tr>`;}))}</section>`);
 const t=transfers.find(t=>t.id===selectedTransfer);if(t&&canWrite()&&writableWarehouses().some(w=>w.id===t.destination_id)&&!['received','closed'].includes(t.status))$('#transfer-detail').insertAdjacentHTML('beforeend',`<button data-action="restore-transfer-loss" data-id="${t.id}">Ajukan kehilangan sisa transit</button>`);
 }};
const oldTransferReceipt=renderTransferReceipt;
renderTransferReceipt=function(){const t=transfers.find(t=>t.id===selectedTransfer);let html=oldTransferReceipt();if(t?.lines.some(l=>Number(l.lost_qty)||Number(l.pending_loss)))html+=`<p class="notice">${t.lines.filter(l=>Number(l.lost_qty)||Number(l.pending_loss)).map(l=>`${esc(l.product_name)} · ${esc(l.batch_number)}: kehilangan disetujui ${fmt(l.lost_qty)}; menunggu ${fmt(l.pending_loss)} ${esc(l.uom)}`).join('<br>')}</p>`;return html;};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action^=restore-transfer-]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();task(async()=>{
 const action=b.dataset.action,id=Number(b.dataset.id);
 if(action==='restore-transfer-preview'||action==='restore-transfer-draft'){const f=$('[data-form=ship]');collectShipment();const body={...Object.fromEntries(new FormData(f)),lines:shipmentLines};const r=await command(action.endsWith('preview')?'preview-transfer':'draft-transfer',body,b);if(action.endsWith('preview')){$('#transfer-plan').innerHTML=table(['Produk','Batch / ED','Qty','HPP','Nilai'],r.lines.map(l=>`<tr><td>${esc(l.name)}</td><td>${esc(l.batch_number)} / ${esc(l.expiry_date)}</td><td>${fmt(l.qty)} ${esc(l.uom)}</td><td>${rupiah(l.unit_cost)}</td><td>${rupiah(Number(l.qty)*Number(l.unit_cost))}</td></tr>`))+`<p>Nilai ${rupiah(r.total)} · Reservasi draft ${r.ttl_hours} jam</p>`;return;}shipmentLines=[{}];}
 if(action==='restore-transfer-dispatch'){const o=operations.documents.find(o=>o.id===id),sender_name=prompt('Nama petugas pengirim:',o.data.dispatch.sender_name||''),vehicle_number=prompt('Nomor kendaraan:',o.data.dispatch.vehicle_number||'');if(!sender_name||!vehicle_number)return;savedShipment=await command('dispatch-transfer',{id,revision:o.revision,sender_name,vehicle_number,shipped_date:localToday()},b);selectedTransfer=savedShipment.id;}
 if(action==='restore-transfer-loss'){const t=transfers.find(t=>t.id===id),reason=prompt('Alasan kehilangan. Sisa yang diajukan ditahan dari penerimaan sampai keputusan:');if(!reason)return;const lines=[];for(const l of t.lines){const remaining=Number(l.remaining)-Number(l.pending_loss||0);if(remaining<=0)continue;const q=prompt(`${l.product_name} · ${l.batch_number}: qty hilang (${l.uom}), maksimal ${remaining}`,String(remaining));if(q===null)return;if(Number(q)>0)lines.push({id:l.id,qty:q});}const r=await command('request-transit-scrap',{transfer_id:id,lines,reason,document_date:localToday()},b);tab='scrap';selectedOperation=r.id;}
 await refresh();render();message('Tersimpan di server.');
 });},true);
const printPoOriginal=printPurchaseOrder, printDoOriginal=printDeliveryOrder;
printPurchaseOrder=async function(id){try{const r=await command('record-print',{kind:'po',id});printPoOriginal(id);message(`Permintaan cetak PO ke-${r.count} tercatat.`);}catch(e){message(e.message,true);}};
printDeliveryOrder=async function(id){try{const r=await command('record-print',{kind:'do',id});printDoOriginal(id);message(`Permintaan cetak DO ke-${r.count} tercatat.`);}catch(e){message(e.message,true);}};
// Expose the last saved usage receipt and history instead of discarding FEFO cost results.
const renderBeforeUsage=render;
render=function(){renderBeforeUsage();if(tab==='stock'){const docs=operations.documents.filter(o=>o.kind==='usage');$('#usage-result').innerHTML=`<h3>Riwayat pemakaian & HPP</h3>${table(['Nomor / tanggal','Gudang / catatan','Qty input','Total HPP','Alokasi batch'],docs.map(o=>`<tr><td>${esc(o.number)}<small>${esc(o.document_date)}</small></td><td>${esc(nameOf(catalog.warehouses,o.warehouse_id))}<small>${esc(o.data.reference)}</small></td><td>${fmt(o.data.input_qty)} ${esc(o.data.input_uom)}</td><td>${rupiah(o.data.cost)}</td><td>${o.data.lines.map(l=>`${esc(l.name)} · ${esc(l.batch_number)} · ${fmt(l.qty)} ${esc(l.uom)} · ${rupiah(Number(l.qty)*Number(l.unit_cost))}`).join('<br>')}</td></tr>`))}`;}if(tab==='scrap'){const o=operations.documents.find(o=>o.id===selectedOperation&&o.kind==='scrap');if(o)$('#content section:nth-child(2)')?.insertAdjacentHTML('beforeend',`<p>Sumber: ${o.data.source==='transit'?'Selisih transit (tidak mengurangi stok gudang lagi)':'Stok gudang'}</p><p class="total">Nilai kerugian: ${rupiah(o.data.total||o.data.lines.reduce((n,l)=>n+Number(l.qty)*Number(l.unit_cost),0))}</p>`);}};
